function minMaxPairSum(nums){
  nums=[...nums].sort((a,b)=>a-b);let maxSum=0;const n=nums.length;
  for(let i=0;i<n/2;i++){maxSum=Math.max(maxSum,nums[i]+nums[n-1-i]);}
  return maxSum;
}
function maxSumSubarrayK(nums,k){
  let windowSum=nums.slice(0,k).reduce((a,b)=>a+b,0);let maxSum=windowSum;
  for(let i=k;i<nums.length;i++){windowSum+=nums[i]-nums[i-k];maxSum=Math.max(maxSum,windowSum);}
  return maxSum;
}
function minMovesToEqual(nums){
  nums=[...nums].sort((a,b)=>a-b);const median=nums[Math.floor(nums.length/2)];
  return nums.reduce((sum,x)=>sum+Math.abs(x-median),0);
}
const minMaxPairSumImpl=minMaxPairSum;
const maxSumSubarrayKImpl=maxSumSubarrayK;
