function addPatternImpl(tracker,pattern,solved){
  if(!tracker[pattern])tracker[pattern]={attempts:0,solves:0};
  tracker[pattern].attempts++;
  if(solved)tracker[pattern].solves++;
}

function getWeakPatternsImpl(tracker,minAttempts=3){
  return Object.entries(tracker)
    .filter(([_,v])=>v.attempts>=minAttempts)
    .map(([k,v])=>({pattern:k,solveRate:v.solves/v.attempts}))
    .sort((a,b)=>a.solveRate-b.solveRate);
}

