const SKILL_TRANSFER=[{contestSkill:'Survey all problems',transferQuality:'Direct'},{contestSkill:'Pattern recognition speed',transferQuality:'Direct'},{contestSkill:'Time budget skip-return',transferQuality:'Adapted'},{contestSkill:'Verify before submit',transferQuality:'Direct'},{contestSkill:'Silent fast coding',transferQuality:'Requires additional practice'}];

function getTransferQuality(skillName){
  const found=SKILL_TRANSFER.find(s=>s.contestSkill===skillName);
  return found?found.transferQuality:null;
}

function needsAdditionalPractice(skills){
  return SKILL_TRANSFER
    .filter(s=>s.transferQuality==='Requires additional practice'&&skills.includes(s.contestSkill))
    .map(s=>s.contestSkill);
}
